// strewed out example of how the grid pattern works:
float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
float JsdChecker(vec2 p) {
    return (sdBox(p-floor(p)-0.5,vec2(1.0))*0.5+0.5)*4.0;
}

// simplified version
// distance to checker walls (normalized from center to walls)
float sdChecker(vec2 p) {
    vec2 q = abs(p-floor(p)-0.5)-vec2(1.0);
    float d = length(max(q,0.0)) + min(max(q.x,q.y),0.0);
    return 2.0*d+2.0; // returning d by itself will not normalize the distance
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;


    float h = sdChecker(uv*10.0);
    if (h >= 0.95) h = 1.0; else h = 0.0;
    vec3 col = vec3(h);


    // Output to screen
    fragColor = vec4(col,1.0);
}
